3: const MAX_CLOCK_SKEW_SECONDS = 60 * 5;
4: 
5: /**
6:  * Verifies a request against Slack's request-signing recipe:
7:  * https://api.slack.com/authentication/verifying-requests-from-slack
8:  *
9:  *   basestring   = `v0:${timestamp}:${rawBody}`
10:  *   signature    = `v0=` + HMAC-SHA256(signingSecret, basestring)
11:  *
12:  * Also rejects requests whose timestamp has drifted more than five
13:  * minutes, which is Slack's own guidance against replay attacks.
14:  */
15: export function verifySlackSignature(options: {
16:   signingSecret: string;
17:   timestamp: string | null;
18:   signature: string | null;
19:   rawBody: string;
20: }): boolean {
21:   const { signingSecret, timestamp, signature, rawBody } = options;
22:   if (!timestamp || !signature) return false;
23: 
24:   const timestampNum = Number(timestamp);
25:   if (!Number.isFinite(timestampNum)) return false;
26: 
27:   const nowSeconds = Math.floor(Date.now() / 1000);
28:   if (Math.abs(nowSeconds - timestampNum) > MAX_CLOCK_SKEW_SECONDS) return false;
29: 
30:   const baseString = `v0:${timestamp}:${rawBody}`;
31:   const expected = `v0=${crypto.createHmac("sha256", signingSecret).update(baseString).digest("hex")}`;
32: 
33:   const expectedBuffer = Buffer.from(expected, "utf8");
34:   const actualBuffer = Buffer.from(signature, "utf8");
35:   if (expectedBuffer.length !== actualBuffer.length) return false;
36: 
37:   return crypto.timingSafeEqual(expectedBuffer, actualBuffer);
38: }
